function drawActor(x,y,face,isPlayer,anim,large=false,flashOn=false){ctx.save();ctx.translate(x,y);ctx.scale(face,1);let s=large?1.55:1,step=Math.sin(anim*9)*3;ctx.scale(s,s);if(flashOn)ctx.globalAlpha=.6+.4*Math.sin(clock*65);
// shadow
ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,73,30,7,0,0,Math.PI*2);ctx.fill();
// legs
rect(-14,45+step,12,25,'#171819');rect(3,45-step,12,25,'#222324');rect(-17,68+step,19,6,'#77766f');rect(2,68-step,21,6,'#77766f');
// coat body and split tails
ctx.fillStyle=isPlayer?'#242526':'#292a2b';ctx.beginPath();ctx.moveTo(-17,18);ctx.lineTo(-13,10);ctx.lineTo(13,10);ctx.lineTo(18,26);ctx.lineTo(14,57);ctx.lineTo(2,52);ctx.lineTo(-4,76);ctx.lineTo(-13,56);ctx.lineTo(-20,66);ctx.lineTo(-18,37);ctx.closePath();ctx.fill();line(-2,17,-2,52,'#77766e',1);line(9,24,7,49,'#555550',2);
// arm and gun
line(12,21,25,34,'#b7b5ad',5);line(25,34,37,29,'#c7c4ba',4);rect(34,26,17,5,'#d1cec3');rect(42,30,5,7,'#85837c');
// neck/head
